verify:
def skill():
    s = Rational(2)
    pr = Rational(-1, 4)
    d2 = (s**2 - 4*pr)*(1 + s**2)
    return sqrt(d2)

def standard():
    a, b = symbols('a b', real=True)
    sol = solve([(a + b)/2 - 1, 4*a*b + 1], [a, b], dict=True)
    assert len(sol) == 2
    d = [sqrt((s[b] - s[a])**2 + (s[b]**2 - s[a]**2)**2) for s in sol]
    assert simplify(d[0] - d[1]) == 0
    return simplify(d[0])

def unique():
    return [standard()]
